#include <bits/stdc++.h>
using namespace std;

int main() {
	int q;
	cin >> q;
	priority_queue<int, vector<int>, greater<>> pq;
	while (q--) {
		int type;
		cin >> type;
		if (type == 1) {
			int x;
			cin >> x;
			pq.push(x);
		}
		else {
			int x = pq.top(); pq.pop();
			cout << x << '\n';
		}
	}
}

#include <bits/stdc++.h>
using namespace std;

int main() {
	int q;
	cin >> q;
	vector<int> c(101);
	while (q--) {
		int type;
		cin >> type;
		if (type == 1) {
			int x;
			cin >> x;
			c[x]++;
		}
		else {
			for (int i = 1; i <= 100; i++) {
				if (c[i] > 0) {
					c[i]--;
					cout << i << '\n';
					break;
				}
			}
		}
	}
}
